1	/* ─── Navbar CSS Module ───────────────────────────────────────────────────────
2	   Extracted verbatim from boldteq-v1-0.webflow.css
3	   All class names preserved exactly; use bracket notation in JSX for hyphenated names
4	   ─────────────────────────────────────────────────────────────────────────── */
5	
6	/* ─── Banner strip ──────────────────────────────────────────────────────────── */
7	
8	/* Skip-to-main-content link — visible only on keyboard focus */
9	.skip-nav:focus {
10	  position: absolute;
11	  left: 0;
12	  top: 0;
13	  z-index: var(--z-modal);
14	  border-bottom-right-radius: 0.5rem;
15	  background-color: #009ce0;
16	  padding: 0.75rem 1.5rem;
17	  font-size: 0.875rem;
18	  font-weight: 600;
19	  color: #fff;
20	  text-decoration: none;
21	  outline-color: #fff;
22	  clip: auto;
23	  width: auto;
24	  height: auto;
25	  margin: 0;
26	  white-space: normal;
27	  overflow: visible;
28	}
